def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    h, w = len(grid), len(grid[0])
    for c in range(w):
        if grid[h-1][c] != 5:
            continue
        active = 5
        for r in range(h-2, -1, -1):
            if grid[r][c] != 0:
                active = grid[r][c]
            else:
                out[r][c] = active
    return out
